from typing import List

class Solution:
    def countGoodNodes(self, edges: List[List[int]]) -> int:
        n = len(edges) + 1
        # Build adjacency list from edges
        graph = [[] for _ in range(n)]
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)

        # Iterative DFS from node 0 (avoids recursion limit on deep trees)
        parent = [-1] * n
        order = []
        stack = [0]
        while stack:
            node = stack.pop()
            order.append(node)
            for child in graph[node]:
                if child != parent[node]:
                    parent[child] = node
                    stack.append(child)

        size = [1] * n          # subtree sizes
        first = [0] * n         # subtree size of the first processed child (0 = none yet)
        good = [True] * n       # all children subtrees have equal size so far

        # Children appear after their parent in `order`, so process in reverse
        for node in reversed(order):
            p = parent[node]
            if p != -1:
                size[p] += size[node]
                if first[p] == 0:
                    first[p] = size[node]
                elif first[p] != size[node]:
                    good[p] = False
        return sum(good)
